600	                                                                   RenameOption option, MailboxSession fromSession, MailboxSession toSession) {
601	        if (option == RenameOption.RENAME_SUBSCRIPTIONS) {
602	            SubscriptionMapper subscriptionMapper = mailboxSessionMapperFactory.getSubscriptionMapper(fromSession);
603	
604	            return subscriptionMapper.findSubscriptionsForUserReactive(fromSession.getUser())
605	                .collectList()
606	                .flatMap(subscriptions -> Flux.fromIterable(renamedResults)
607	                    .concatMap(renamedResult -> {
608	                        Function<Subscription, Mono<Void>> renameFunction = subscription -> subscriptionMapper.deleteReactive(subscription)
609	                            .then(subscriptionMapper.saveReactive(new Subscription(toSession.getUser(), renamedResult.getDestinationPath().asEscapedString())));
610	                        Subscription legacySubscription = new Subscription(fromSession.getUser(), renamedResult.getOriginPath().getName());
611	                        if (subscriptions.contains(legacySubscription)) {
612	                            return renameFunction.apply(legacySubscription);
613	                        }
614	                        Subscription subscription = new Subscription(fromSession.getUser(), renamedResult.getOriginPath().asEscapedString());
615	                        if (subscriptions.contains(subscription)) {
616	                            return renameFunction.apply(subscription);
617	                        }
618	                        return Mono.empty();
619	                    })
620	                    .then()
621	                    .thenReturn(renamedResults));
622	        }
623	        return Mono.just(renamedResults);
624	    }
